{"backendPid":175,"connection":"setup-30db498bba9e4c91a6aeb64d83fb46ff","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":9,"sql":"CREATE FUNCTION \"model_51b65f30db264a7c\".\"before\"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE k bigint; p uuid; live boolean; v uuid; BEGIN\nIF TG_OP<>'DELETE' AND (NEW.id IS NULL OR NEW.balance IS NULL OR NEW.active IS NULL OR NEW.region IS NULL) THEN RETURN NEW; END IF;\nIF TG_OP='UPDATE' AND NEW.id IS DISTINCT FROM OLD.id THEN RAISE EXCEPTION 'primary key mutation'; END IF;\nk:=CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END;\nSELECT version,present INTO p,live FROM \"model_51b65f30db264a7c\".\"state\" WHERE key=k FOR UPDATE;\nIF NOT FOUND THEN RAISE EXCEPTION 'key outside configured domain'; END IF;\nIF TG_OP<>'INSERT' AND (NOT live OR p IS DISTINCT FROM OLD.version) THEN RAISE EXCEPTION 'source mismatch'; END IF;\nv:=gen_random_uuid();\nINSERT INTO \"model_51b65f30db264a7c\".\"candidates\" VALUES(v,k,p,TG_OP,live,TG_OP<>'DELETE',CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END);\nIF TG_OP='DELETE' THEN RETURN OLD; ELSE NEW.version:=v; RETURN NEW; END IF;\nEND$model$","transaction":"setup-30db498bba9e4c91a6aeb64d83fb46ff-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":175,"connection":"setup-30db498bba9e4c91a6aeb64d83fb46ff","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":10,"sql":"CREATE FUNCTION \"model_51b65f30db264a7c\".\"after\"() RETURNS trigger LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE v uuid; c record; n integer; BEGIN\nv:=CASE WHEN TG_OP='DELETE' THEN \"model_51b65f30db264a7c\".\"delete_token\"(OLD.id,OLD.version) ELSE NEW.version END;\nSELECT * INTO c FROM \"model_51b65f30db264a7c\".\"candidates\" WHERE version=v;\nIF NOT FOUND OR c.action<>TG_OP OR c.key IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN OLD.id ELSE NEW.id END) OR c.image IS DISTINCT FROM (CASE WHEN TG_OP='DELETE' THEN NULL ELSE jsonb_build_object('balance',NEW.balance::text,'active',NEW.active,'region',NEW.region) END) THEN RAISE EXCEPTION 'actual effect mismatch'; END IF;\nIF TG_OP='INSERT' AND c.old_present THEN RAISE EXCEPTION 'insert presence mismatch'; END IF;\nUPDATE \"model_51b65f30db264a7c\".\"state\" SET version=v,present=(TG_OP<>'DELETE') WHERE key=c.key AND version IS NOT DISTINCT FROM c.predecessor AND present=c.old_present;\nGET DIAGNOSTICS n=ROW_COUNT; IF n<>1 THEN RAISE EXCEPTION 'effect state mismatch'; END IF;\nINSERT INTO \"model_51b65f30db264a7c\".\"effects\" SELECT * FROM \"model_51b65f30db264a7c\".\"candidates\" WHERE version=v;\nIF TG_OP='DELETE' THEN RETURN OLD; ELSE RETURN NEW; END IF;\nEND$model$","transaction":"setup-30db498bba9e4c91a6aeb64d83fb46ff-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":175,"connection":"setup-30db498bba9e4c91a6aeb64d83fb46ff","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":11,"sql":"CREATE FUNCTION \"model_51b65f30db264a7c\".\"predecessor\"(v uuid) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE n integer; p uuid; BEGIN SELECT count(*),min(predecessor::text)::uuid INTO n,p FROM \"model_51b65f30db264a7c\".\"candidates\" WHERE version=v; IF n<>1 THEN RAISE EXCEPTION 'predecessor not unique'; END IF; RETURN p; END$model$","transaction":"setup-30db498bba9e4c91a6aeb64d83fb46ff-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
{"backendPid":175,"connection":"setup-30db498bba9e4c91a6aeb64d83fb46ff","kind":"control-query","parameters":null,"result":{"actualPGresult":{"commandTag":{"base64":"Q1JFQVRFIEZVTkNUSU9O","captureType":"bytes"},"commandTuples":null,"fields":[],"nfields":0,"ntuples":0,"rawRows":[],"status":1},"columns":null,"commandTag":"CREATE FUNCTION","complete":true,"rowcount":-1,"rows":[],"status":1},"sourceSeq":12,"sql":"CREATE FUNCTION \"model_51b65f30db264a7c\".\"delete_token\"(k bigint,p uuid) RETURNS uuid LANGUAGE plpgsql VOLATILE SECURITY INVOKER SET search_path=pg_catalog AS $model$DECLARE n integer; v uuid; BEGIN SELECT count(*),min(version::text)::uuid INTO n,v FROM \"model_51b65f30db264a7c\".\"candidates\" WHERE key=k AND predecessor=p AND action='DELETE'; IF n<>1 THEN RAISE EXCEPTION 'delete not unique'; END IF; RETURN v; END$model$","transaction":"setup-30db498bba9e4c91a6aeb64d83fb46ff-tx-1","transactionStatusAfter":"INTRANS","transactionStatusBefore":"INTRANS"}
